ruleToc.chapterList:
$.result.list
@js://二级目录
//章节名显示卷名(true/false
var opts = {
	showVolName: false
}

//净化章节名
function format(title){
	return title.trim().replace(/^(\d+)(?![\s\d卷部章节回.])/, '$1 ').replace(/\s+/g, "\x20\x20")
}


var list = []
JSON.parse(result).forEach(vol => {
	var chs = vol.list.map(ch => ({
			text: !vol.name?format(ch.name):((opts.showVolName?format(vol.name)+'☪ ':'').padStart(3,''))+format(ch.name).replace(/^(正文|VIP章节|最新章节)?(\s+|_)|[\(（【].*[求更谢乐发推订贺加补].*/g,''),
			href: '/cdn/book/content/'+java.get('id')+'/'+ch.id+'.html'
		}))
	if(vol.name!=""){
			list.push({
					text: '📖['+format(vol.name)+']📖',
					VolName: true
				})
		}
	list = list.concat(chs)
})
list

